public struct FfiConverterTypeConnCore: FfiConverter {
    typealias FfiType = UInt64
    typealias SwiftType = ConnCore

    public static func lift(_ handle: UInt64) throws -> ConnCore {
        return ConnCore(unsafeFromHandle: handle)
    }

    public static func lower(_ value: ConnCore) -> UInt64 {
        return value.uniffiCloneHandle()
    }

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> ConnCore {
        let handle: UInt64 = try readInt(&buf)
        return try lift(handle)
    }

    public static func write(_ value: ConnCore, into buf: inout [UInt8]) {
        writeInt(&buf, lower(value))
    }
}


