    func onStatus(status: FfiConnectionStatus) 
    
    func onBearerIssued(token: String) 
    
    func onShell(snapshot: FfiShellSnapshot) 
    
    func onThread(snapshot: FfiThreadSnapshot) 
    
    func onError(message: String) 
    
}
